struct StTensorDesc { const char* name; const char* level; int channels; const char* fmt; bool pp; };
struct StInDesc { const char* name; bool linear; };
struct StPassDesc
{
    const char* file; const char* outLevel; const char* inLevel;
    StInDesc in[24]; int nIn; const char* out[16]; int nOut; const uint32_t* spv; size_t spvBytes;
    int wgx, wgy;  // workgroup size of a compute pass (the plan "wg" line, else 8 x 8)
    int ppx, ppy;  // pixels per thread of a compute pass ("wg FILE X Y PPX PPY", else 1 x 1)
    bool fragment; // "fpass": a fragment pass, out[] are colour attachments (MRT) in location order,
                   // push constants osize / isize in the fragment stage, the full-screen triangle
};
